solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static const tree *find(const tree *r, const char *l) {
    if (!strcmp(r->label, l))
        return r;
    for (size_t i = 0; i < r->count; i++) {
        const tree *t = find(r->children[i], l);
        if (t)
            return t;
    }
    return NULL;
}
static const tree *parent(const tree *r, const tree *t) {
    for (size_t i = 0; i < r->count; i++) {
        if (r->children[i] == t)
            return r;
        const tree *p = parent(r->children[i], t);
        if (p)
            return p;
    }
    return NULL;
}
static tree *clone(const tree *root, const tree *r, const tree *previous) {
    tree *t = (tree *)calloc(1, sizeof(tree));
    t->label = r->label;
    const tree *p = parent(root, r);
    for (size_t i = 0; i <= r->count; i++) {
        const tree *c = i == r->count ? p : r->children[i];
        if (!c || c == previous)
            continue;
        t->children = (tree **)realloc(t->children, (t->count + 1) * sizeof(tree *));
        t->children[t->count++] = clone(root, c, r);
    }
    return t;
}
tree *from_pov(const tree *r, const char *l) {
    if (!r)
        return NULL;
    const tree *t = find(r, l);
    return t ? clone(r, t, NULL) : NULL;
}
static bool path(const tree *root, const tree *r, const tree *previous, const char *to,
                 const char **out, size_t *count) {
    out[(*count)++] = r->label;
    if (!strcmp(r->label, to))
        return true;
    const tree *p = parent(root, r);
    for (size_t i = 0; i <= r->count; i++) {
        const tree *c = i == r->count ? p : r->children[i];
        if (c && c != previous && path(root, c, r, to, out, count))
            return true;
    }
    --*count;
    return false;
}
size_t path_to(const tree *r, const char *from, const char *to, const char **out) {
    if (!r)
        return 0;
    const tree *t = find(r, from);
    if (!t || !find(r, to))
        return 0;
    size_t n = 0;
    path(r, t, NULL, to, out, &n);
    return n;
}
void tree_free(tree *r) {
    if (!r)
        return;
    for (size_t i = 0; i < r->count; i++)
        tree_free(r->children[i]);
    free(r->children);
    free(r);
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    tree a = {"a", NULL, 0}, b = {"b", NULL, 0}, c = {"c", NULL, 0};
    tree *bc[] = {&c};
    b.children = bc;
    b.count = 1;
    tree *ab[] = {&a, &b};
    tree r = {"r", ab, 2};
    const char *o[10];
    assert(path_to(&r, "a", "c", o) == 4 && !strcmp(o[0], "a") && !strcmp(o[1], "r") &&
           !strcmp(o[3], "c"));
    assert(path_to(&r, "x", "c", o) == 0);
    tree *t = from_pov(&r, "c");
    assert(t && !strcmp(t->label, "c") && !strcmp(t->children[0]->label, "b") &&
           !strcmp(t->children[0]->children[0]->label, "r"));
    tree_free(t);
    assert(!from_pov(&r, "x"));

    return 0;
}
